namespace PZ3D {
 static class GameStartupMonitorTests {
  static void Check(bool ok,string message){if(!ok)throw new Exception("FAIL: "+message);Console.WriteLine("PASS: "+message);}
  static Type Required(string name){var t=typeof(GameStartupLaunch).Assembly.GetType("PZ3D."+name);Check(t!=null,name+" exists");return t;}
  static object New(string name,params object[] args){return Activator.CreateInstance(Required(name),BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public,null,args,null);}
  static object Call(object target,string name,params object[] args){try{return target.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Invoke(target,args);}catch(TargetInvocationException e){throw e.InnerException;}}
  static string Log(string body){return "LOG  : General      f:0 st:0> "+body;}
  static GameStartupSnapshot Snapshot(object reducer){return (GameStartupSnapshot)Call(reducer,"Snapshot",DateTime.UtcNow);}
  [StructLayout(LayoutKind.Sequential)]struct NativeMemoryStatus {public uint Length,Load;public ulong Total,Available,PageTotal,PageAvailable,VirtualTotal,VirtualAvailable,Extended;}
  [DllImport("kernel32.dll",SetLastError=true)][return:MarshalAs(UnmanagedType.Bool)]static extern bool GlobalMemoryStatusEx(ref NativeMemoryStatus value);
  static long PhysicalTotal(){var value=new NativeMemoryStatus{Length=(uint)Marshal.SizeOf(typeof(NativeMemoryStatus))};if(!GlobalMemoryStatusEx(ref value))throw new Exception("fixture OS memory query failed");return checked((long)value.Total);}
  // Break caught: arbitrary main-class mentions, stack frames and earlier states falsely finish startup.
  static void Evidence(){
   var launch=new GameStartupLaunch{SessionId="00112233445566778899aabbccddeeff",StartedUtc=DateTime.UtcNow,Stage="submitted"};
   object r=New("GameStartupReducer",launch);
   foreach(string noise in new[]{"zombie.gameStates.MainScreenState",Log("STATE: exit zombie.gameStates.TermsOfServiceState"),Log(" at zombie.gameStates.MainScreenState.enter(MainScreenState.java:42)"),"LOG  : Lua          f:0> AuthPending,",Log("Loading MainScreenState.enter 2"),Log("[SomeMod] MainScreenState.enter 2"),"DEBUG: ExitDebug f:0 at MainScreenState.enter > MainScreenState.enter 2","LOG  : Lua f:0> [OZL-STARTUP] menu-ready ffeeddccbbaa99887766554433221100",Log("[OZL-STARTUP] menu-ready "+launch.SessionId),"ERROR: Lua f:0> [OZL-STARTUP] menu-ready "+launch.SessionId})Call(r,"Line",noise);
   Check(!Snapshot(r).Complete&&!Snapshot(r).WaitingForInput,"class, stack, mod and network mentions are not readiness or authorization evidence");
   Call(r,"Line",Log("Loading Lua"));Check(Snapshot(r).Stage=="lua"&&!Snapshot(r).CompletedItems.HasValue&&!Snapshot(r).TotalItems.HasValue,"actual phase preserves unknown item progress");
   Call(r,"Line",Log("Waiting for Java mods approval…"));Check(Snapshot(r).WaitingForInput,"verified Buddy approval marker yields foreground");
   Call(r,"Line",Log("Loading Mods"));Check(!Snapshot(r).WaitingForInput&&Snapshot(r).Stage=="mods","actual post-approval stage clears waiting");
   Call(r,"Line","LOG  : Lua          f:0 st:0> [OZL-STARTUP] menu-ready "+launch.SessionId);Check(Snapshot(r).Complete,"verified bridge marker with this session nonce confirms main menu");
   object fake=New("GameStartupReducer",launch);Call(fake,"Line",Log("MainScreenState.enter 2"));Check(!Snapshot(fake).Complete,"wrong logger category cannot impersonate enter-end evidence");
  }
  // Break caught: accumulated raw log data leaks secrets or grows without limit.
  static void Bounds(){object r=New("GameStartupReducer",new GameStartupLaunch{StartedUtc=DateTime.UtcNow});for(int i=0;i<100;i++)Call(r,"Line",Log("row "+i+" password=fixture-secret "+new string('x',9000)));var s=Snapshot(r);Check(s.Lines.Length==80&&s.Lines.All(l=>l.Length<=4096&&!l.Contains("fixture-secret")),"retains 80 bounded sanitized lines");}
  // Break caught: startup only shows a generic tail, silently dropping unknown errors and arbitrary mod evidence.
  static Array Issues(GameStartupSnapshot snapshot){var field=typeof(GameStartupSnapshot).GetField("Issues");Check(field!=null,"startup snapshots expose independent problem observations");return (Array)field.GetValue(snapshot);}
  static string IssueText(Array issues){var b=new StringBuilder();foreach(object issue in issues){foreach(string name in new[]{"title","meaning","advice"})b.AppendLine(Convert.ToString(issue.GetType().GetField(name).GetValue(issue)));foreach(string mod in (string[])issue.GetType().GetField("mods").GetValue(issue))b.AppendLine(mod);foreach(object evidence in (Array)issue.GetType().GetField("evidence").GetValue(issue))b.AppendLine(Convert.ToString(evidence.GetType().GetField("text").GetValue(evidence)));}return b.ToString();}
  static void ProblemObservations(){
   var launch=new GameStartupLaunch{SessionId="00112233445566778899aabbccddeeff",StartedUtc=DateTime.UtcNow,Stage="submitted"};object r=New("GameStartupReducer",launch);
   Call(r,"Line",Log("Loading Lua"));Check(Issues(Snapshot(r)).Length==0,"ordinary loading produces no invented issue");
   Call(r,"Line","ERROR: Lua f:0> attempted index: health of non-table: null");Call(r,"Line","Lua((MOD:Unseen Solar Observatory)).tick(SolarProbe.lua:73)");
   var current=(GameStartupSnapshot)Call(r,"Snapshot",DateTime.UtcNow.AddSeconds(1));string text=IssueText(Issues(current));Check(text.Contains("Unseen Solar Observatory")&&text.Contains("health")&&text.Contains("SolarProbe.lua")&&System.Text.RegularExpressions.Regex.IsMatch(text,"[\u4e00-\u9fff]"),"arbitrarily named mod problems retain original evidence and Chinese explanation");
   Check(!current.Complete&&!current.Failed&&current.Stage=="lua","observing a Lua ERROR neither invents readiness nor interrupts launch");
   foreach(object item in Issues(current))item.GetType().GetField("meaning").SetValue(item,"mutated fixture snapshot");Check(!IssueText(Issues((GameStartupSnapshot)Call(r,"Snapshot",DateTime.UtcNow.AddSeconds(1)))).Contains("mutated fixture snapshot"),"UI snapshot mutation cannot corrupt retained startup evidence");
   for(int i=0;i<400;i++)Call(r,"Line",Log("ordinary new row "+i));current=(GameStartupSnapshot)Call(r,"Snapshot",DateTime.UtcNow.AddSeconds(2));Check(IssueText(Issues(current)).Contains("Unseen Solar Observatory"),"bounded rolling log eviction preserves earlier observed problems");
   Call(r,"Line","ERROR: General f:0> utterly unfamiliar fixture anomaly password=fixture-secret");Call(r,"Line",@"WARN : General f:0> unfamiliar resource warning at C:\PrivateFixture\user.log");
   current=(GameStartupSnapshot)Call(r,"Snapshot",DateTime.UtcNow.AddSeconds(3));text=IssueText(Issues(current));Check(text.Contains("utterly unfamiliar fixture anomaly")&&text.Contains("unfamiliar resource warning")&&!text.Contains("fixture-secret")&&!text.Contains("PrivateFixture"),"unknown errors and warnings remain visible with sanitized original evidence");
   Call(r,"Line","java.lang.OutOfMemoryError: Java heap space");Call(r,"Line","LOG  : Lua f:0> [OZL-STARTUP] menu-ready "+launch.SessionId);current=(GameStartupSnapshot)Call(r,"Snapshot",DateTime.UtcNow.AddSeconds(4));Check(current.Complete&&!current.Failed&&IssueText(Issues(current)).Contains("Java heap space"),"fatal-looking log observation preserves the strict successful ready marker and problem evidence");
   Call(r,"Line","ERROR: General f:0> trailing observation after menu");current=(GameStartupSnapshot)Call(r,"Snapshot",DateTime.UtcNow.AddSeconds(5));Check(current.Complete&&!current.Failed&&IssueText(Issues(current)).Contains("trailing observation after menu"),"later issue tails cannot turn successful startup into failure");
   for(int i=0;i<400;i++)Call(r,"Line","ERROR: General f:0> distinct bounded observation "+i+new string('z',1000));current=(GameStartupSnapshot)Call(r,"Snapshot",DateTime.UtcNow.AddSeconds(6));Check(Issues(current).Length>0&&Issues(current).Length<=24&&IssueText(Issues(current)).Length<65536,"startup problem history and displayed evidence remain bounded during noisy logs");
   object next=New("GameStartupReducer",launch);Check(Issues(Snapshot(next)).Length==0,"new startup observation never reuses another session problems");
  }
  // Break caught: a single poll evicts an early problem before the first snapshot can analyze it.
  static void BurstProblems(){
   foreach(int width in new[]{0,3800}){
    object r=New("GameStartupReducer",new GameStartupLaunch{StartedUtc=DateTime.UtcNow,Stage="submitted"});Call(r,"Line","ERROR: General f:0> first-poll burst anomaly");
    int count=width==0?200:60;for(int i=0;i<count;i++)Call(r,"Line",Log("ordinary burst row "+i+new string('n',width)));
    var current=Snapshot(r);Check(IssueText(Issues(current)).Contains("first-poll burst anomaly")&&!current.Failed&&!current.Complete,"one poll preserves its early ERROR across "+(width==0?"line":"byte")+" buffer eviction before the first snapshot");
   }
   DateTime at=DateTime.UtcNow;object throttled=New("GameStartupReducer",new GameStartupLaunch{StartedUtc=at});Call(throttled,"Line",Log("ordinary initial row"));Call(throttled,"Snapshot",at);Call(throttled,"Line","ERROR: General f:0> pending throttled anomaly");Check(Issues((GameStartupSnapshot)Call(throttled,"Snapshot",at.AddMilliseconds(100))).Length==0,"ordinary snapshot analysis remains throttled within 500 milliseconds");Check(IssueText(Issues((GameStartupSnapshot)Call(throttled,"Snapshot",at.AddMilliseconds(501)))).Contains("pending throttled anomaly"),"ordinary pending evidence is collected on the next allowed snapshot");
   Call(throttled,"Line","ERROR: General f:0> throttled burst anomaly");for(int i=0;i<200;i++)Call(throttled,"Line",Log("ordinary throttled burst row "+i));Check(IssueText(Issues((GameStartupSnapshot)Call(throttled,"Snapshot",at.AddMilliseconds(502)))).Contains("throttled burst anomaly"),"overflow chunk collection preserves problems even between normally throttled snapshots");
   object boundary=New("GameStartupReducer",new GameStartupLaunch{StartedUtc=DateTime.UtcNow});for(int i=0;i<159;i++)Call(boundary,"Line",Log("ordinary context "+i));Call(boundary,"Line","ERROR: Lua f:0> attempted index: moon of non-table: null");Call(boundary,"Line","Lua((MOD:Boundary Telescope)).tick(Telescope.lua:91)");for(int i=0;i<200;i++)Call(boundary,"Line",Log("ordinary continuation "+i));Check(IssueText(Issues(Snapshot(boundary))).Contains("Boundary Telescope"),"chunk overlap preserves arbitrary mod frames following an ERROR at the flush boundary");
  }
  // Break caught: initial bytes, half-lines or a replaced/truncated file are treated as fresh complete lines incorrectly.
  static void Tail(string root){string path=Path.Combine(root,"console.txt");File.WriteAllText(path,Log("MainScreenState.enter 2")+"\nold partial",new UTF8Encoding(false));object tail=New("GameStartupLogTail",path);Check(((string[])Call(tail,"Read")).Length==0,"initial log boundary rejects all old bytes");File.AppendAllText(path,"suffix\n"+Log("Loading "),new UTF8Encoding(false));Check(((string[])Call(tail,"Read")).Length==0,"old half-line suffix and fresh half-line are withheld");File.AppendAllText(path,"Lua\n",new UTF8Encoding(false));string[] lines=(string[])Call(tail,"Read");Check(lines.Length==1&&lines[0]==Log("Loading Lua"),"half-line append is joined exactly once");File.WriteAllText(path,Log("Loading Mods")+"\n",new UTF8Encoding(false));Check(((string[])Call(tail,"Read")).Single()==Log("Loading Mods"),"same-file truncation restarts from fresh beginning");File.Move(path,path+".old");File.WriteAllText(path,Log("Loading Clothing")+"\n",new UTF8Encoding(false));Check(((string[])Call(tail,"Read")).Single()==Log("Loading Clothing"),"rotation follows new file identity");File.WriteAllText(path,new string('x',300000)+"\n"+Log("Loading Lua")+"\n",new UTF8Encoding(false));string[] first=(string[])Call(tail,"Read");Check(first.Length==0,"one tick cannot consume over 256 KiB or expose oversized partial");string[] second=(string[])Call(tail,"Read");Check(second.Length<=2&&second.Any(x=>x==Log("Loading Lua"))&&second.All(x=>x.Length<=4096),"oversized line is discarded without losing next line");}
  // Break caught: path/name-only or prior-process matching attaches an unrelated process.
  static void Identity(string root){Type t=Required("GameStartupMonitor");var method=t.GetMethod("MatchesClientIdentity",BindingFlags.Static|BindingFlags.NonPublic);DateTime now=DateTime.UtcNow;Func<string,string,DateTime,bool,bool> match=(name,image,birth,client)=>(bool)method.Invoke(null,new object[]{root,now,name,image,birth,client});Check(!match("ProjectZomboid64",Path.Combine(root,"ProjectZomboid64.exe"),now.AddSeconds(-1),true),"preexisting native client rejected");Check(!match("ProjectZomboid64",Path.Combine(root,"other","ProjectZomboid64.exe"),now.AddSeconds(1),true),"same executable name outside game rejected");Check(match("ProjectZomboid64",Path.Combine(root,"ProjectZomboid64.exe"),now.AddSeconds(1),true),"new exact native client accepted");Check(!match("java",Path.Combine(root,"jre64","bin","java.exe"),now.AddSeconds(1),false),"server or unknown Java role rejected");Check(match("java",Path.Combine(root,"jre64","bin","java.exe"),now.AddSeconds(1),true),"only classified new bundled Java client accepted");}
  // Break caught: closing observation stops the game or still emits callbacks, or heap is presented as working set.
  static void Lifecycle(string root){Directory.CreateDirectory(Path.Combine(root,"game"));Directory.CreateDirectory(Path.Combine(root,"user"));File.WriteAllText(Path.Combine(root,"game","ProjectZomboid64.json"),"{\"vmArgs\":[\"-Xmx6g\"]}");GameStartupSnapshot last=null;int count=0;object gate=new object();Action<GameStartupSnapshot> changed=s=>{lock(gate){last=s;count++;}};var launch=new GameStartupLaunch{SessionId="life",GamePath=Path.Combine(root,"game"),UserPath=Path.Combine(root,"user"),StartedUtc=DateTime.UtcNow,Stage="preparing"};using(var monitor=(IDisposable)New("GameStartupMonitor",launch,changed)){Call(monitor,"Start");Call(monitor,"Submitted");for(int i=0;i<100;i++){lock(gate){if(last!=null&&last.HeapLimitBytes.HasValue)break;}Thread.Sleep(20);}lock(gate){Check(last!=null&&last.HeapLimitBytes==6442450944L&&!last.WorkingSetBytes.HasValue&&last.TotalPhysicalBytes>0,"heap limit and physical system memory remain separate from unbound working set");}Call(monitor,"Fail","password=fixture-secret reason");lock(gate){Check(last.Failed&&!last.Message.Contains("fixture-secret"),"launch failure retained and sanitized");}}int stopped;lock(gate){stopped=count;}Thread.Sleep(650);lock(gate){Check(stopped==count,"dispose stops callbacks without any process side effects");}}
  static bool Wait(Func<bool> value){for(int i=0;i<160;i++){if(value())return true;Thread.Sleep(25);}return false;}
  // Break caught: the memory denominator silently discards sub-GiB physical RAM.
  static void PhysicalPrecision(string root){string game=Path.Combine(root,"physical-precision"),user=Path.Combine(root,"physical-user");Directory.CreateDirectory(game);Directory.CreateDirectory(user);long expected=PhysicalTotal();GameStartupSnapshot last=null;object gate=new object();using(var monitor=(IDisposable)New("GameStartupMonitor",new GameStartupLaunch{GamePath=game,UserPath=user,StartedUtc=DateTime.UtcNow},(Action<GameStartupSnapshot>)(s=>{lock(gate){last=s;}}))){Call(monitor,"Start");Check(Wait(()=>{lock(gate){return last!=null&&last.TotalPhysicalBytes.HasValue;}}),"observer reads actual total physical memory");lock(gate){Check(last.TotalPhysicalBytes==expected,"physical memory denominator retains all bytes reported by the OS");}}}
  // Break caught: rounding configured heap to GiB misrepresents non-integral
  // limits (for example -Xmx1536m must remain exactly 1610612736 bytes).
  static void HeapPrecision(string root){string game=Path.Combine(root,"heap-precision"),user=Path.Combine(root,"heap-user");Directory.CreateDirectory(game);Directory.CreateDirectory(user);string config=Path.Combine(game,"ProjectZomboid64.json");string[] args={"1536m","2560m","1572864k","1610612736","1k"};long[] expected={1610612736L,2684354560L,1610612736L,1610612736L,1024L};for(int i=0;i<args.Length;i++){File.WriteAllText(config,"{\"vmArgs\":[\"-Xmx8g\",\"-Xmx"+args[i]+"\"]}");using(var monitor=(IDisposable)New("GameStartupMonitor",new GameStartupLaunch{GamePath=game,UserPath=user,StartedUtc=DateTime.UtcNow},(Action<GameStartupSnapshot>)(s=>{}))){Check((long?)Call(monitor,"ReadHeap")==expected[i],"effective heap retains exact byte limit for -Xmx"+args[i]);}}}
  static Process Helper(string image){var p=Process.Start(new ProcessStartInfo(image){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true});if(p.StandardOutput.ReadLine()!="owned fixture")throw new Exception("helper did not start");return p;}
  static void StopHelper(Process p){if(p==null)return;try{p.StandardInput.WriteLine("finish");p.WaitForExit(5000);}finally{p.Dispose();}}
  // Break caught: log markers without a matching fresh process finish the session,
  // closing the observer terminates its client, or live working set is fabricated.
  static void RealProcess(string root){
   string game=Path.Combine(root,"process-game"),user=Path.Combine(root,"process-user");Directory.CreateDirectory(game);Directory.CreateDirectory(user);string image=Path.Combine(game,"ProjectZomboid64.exe"),console=Path.Combine(user,"console.txt");
   using(var compiler=System.CodeDom.Compiler.CodeDomProvider.CreateProvider("CSharp")){var options=new System.CodeDom.Compiler.CompilerParameters(new[]{"System.dll"},image){GenerateExecutable=true,TempFiles=new System.CodeDom.Compiler.TempFileCollection(root,false)};var built=compiler.CompileAssemblyFromSource(options,"using System; class Owned { static void Main(){Console.WriteLine(\"owned fixture\");Console.In.ReadLine();} }");Check(!built.Errors.HasErrors,"owned native-image fixture compiles");}
   File.WriteAllText(Path.Combine(game,"ProjectZomboid64.json"),"{\"vmArgs\":[\"-Xmx2g\"]}");File.WriteAllText(console,"LOG  : ExitDebug    f:0> MainScreenState.enter 2\n");Process old=null,fresh=null;IDisposable monitor=null;GameStartupSnapshot last=null;object gate=new object();Action<GameStartupSnapshot> changed=s=>{lock(gate){last=s;}};
   try{old=Helper(image);Thread.Sleep(50);var launch=new GameStartupLaunch{SessionId="owned",GamePath=game,UserPath=user,StartedUtc=DateTime.UtcNow,Stage="submitted"};monitor=(IDisposable)New("GameStartupMonitor",launch,changed);Call(monitor,"Start");Check(Wait(()=>{lock(gate){return last!=null;}}),"background observer publishes");Thread.Sleep(600);lock(gate){Check(!last.ProcessId.HasValue&&!last.Complete&&last.Lines.Length==0,"old real process and stale ready log cannot bind or complete");}
    File.WriteAllText(Path.Combine(game,"ProjectZomboid64.json"),"{\"vmArgs\":[\"-Xmx4g\"]}");fresh=Helper(image);File.AppendAllText(console,Log("Loading Lua")+"\n");Check(Wait(()=>{lock(gate){return last!=null&&last.ProcessId==fresh.Id&&last.Stage=="lua";}}),"fresh exact real process binds and reads only appended loading logs");lock(gate){Check(last.WorkingSetBytes>0&&last.HeapLimitBytes==4294967296L,"actual process working set measured and effective launch heap refreshed");}
    monitor.Dispose();monitor=null;Thread.Sleep(600);Check(!fresh.HasExited&&!old.HasExited,"closing observer leaves both owned processes running");
    StopHelper(fresh);fresh=null;launch.StartedUtc=DateTime.UtcNow;last=null;monitor=(IDisposable)New("GameStartupMonitor",launch,changed);Call(monitor,"Start");fresh=Helper(image);Check(Wait(()=>{lock(gate){return last!=null&&last.ProcessId==fresh.Id;}}),"second session binds only its new client");using(var locked=new FileStream(console,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){StopHelper(fresh);fresh=null;Check(Wait(()=>{lock(gate){return last!=null&&last.Failed;}}),"early process exit reports failure even while console is locked");}
   }finally{if(monitor!=null)monitor.Dispose();StopHelper(fresh);StopHelper(old);}
  }
  // Break caught: constructing the UI monitor just after launch loses a ready
  // record already printed by this unique session, or replays unrelated old logs.
  static void LateBoundary(string root){string game=Path.Combine(root,"process-game"),user=Path.Combine(root,"process-user"),console=Path.Combine(user,"console.txt");var launch=new GameStartupLaunch{SessionId="102132435465768798a9bacbdcedfe0f",GamePath=game,UserPath=user,StartedUtc=DateTime.UtcNow,Stage="submitted"};Process child=null;IDisposable monitor=null;GameStartupSnapshot last=null;object gate=new object();try{child=Helper(Path.Combine(game,"ProjectZomboid64.exe"));File.WriteAllText(console,Log("Loading Scripts")+"\nLOG  : Lua f:0> [OZL-STARTUP] menu-ready ffeeddccbbaa99887766554433221100\nLOG  : Lua f:0> [OZL-STARTUP] menu-ready "+launch.SessionId+"\n");using(var locked=new FileStream(console,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){monitor=(IDisposable)New("GameStartupMonitor",launch,(Action<GameStartupSnapshot>)(s=>{lock(gate){last=s;}}));Call(monitor,"Start");Thread.Sleep(650);}Check(Wait(()=>{lock(gate){return last!=null&&last.Complete;}}),"late observer retries initial log lock and recovers this nonce ready after matching fresh client");lock(gate){Check(last.ProcessId==child.Id&&last.Lines.Length==1&&last.Lines[0].EndsWith(launch.SessionId),"boundary recovery does not replay old phases or different-session evidence");}}finally{if(monitor!=null)monitor.Dispose();StopHelper(child);}}
  public static int Main(){string root=Path.Combine(Path.GetTempPath(),"ozl-startup-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{Evidence();Bounds();ProblemObservations();BurstProblems();Tail(root);Identity(root);PhysicalPrecision(root);HeapPrecision(root);Lifecycle(root);RealProcess(root);LateBoundary(root);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}finally{Directory.Delete(root,true);}}
 }
